"use strict";
const test=require("node:test"),assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path");
const {fixture,facts,workspaceRef}=require("./oath-candidate-fixture.cjs"),{createOathCandidateRead}=require("../services/oath-candidate-read");
const {taskKey}=require("../domain/oath-workspace");
const owner=()=>{const cleanup=[];return{cleanup,register:fn=>cleanup.push(fn),close(){cleanup.splice(0).forEach(fn=>fn());}};};
const gate=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return{promise,resolve,reject};};
async function ready(f){const component=owner(),reader=createOathCandidateRead(f.oath,component);await reader.selectWorkspace({type:"project",id:"private"});return{reader,component};}
test("candidate reader, final requirements and explicit enrollment bridge match original take",async t=>{
 const results=[];for(const current of[false,true]){const f=fixture({original:!current});t.after(()=>f.close());const {reader,component}=await ready(f);t.after(()=>component.close());const tasks=current?reader.state.tasks:f.read({type:"project",id:"private"});assert.deepEqual(facts(tasks),require("./oath-candidate-baseline.json")[0].candidates);const draft=f.draft(tasks),submitted=current?reader.enrollmentDraft(draft):draft;f.oath.validateDraft(submitted);await f.oath.take(submitted);results.push({snapshot:f.snapshot(),saved:f.saved,current:f.oath.current});}assert.deepEqual(results[1],results[0]);
});
test("cached candidate reads and requirement/clock changes never rescan or allocate IDs",async t=>{const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f);t.after(()=>component.close());const counts={...f.counts},before=f.snapshot(),draft=f.draft(reader.state.tasks.slice(0,1));for(let i=0;i<10;i++){await reader.read();reader.requirements(draft);f.oath.tickDisplay();}assert.deepEqual(f.counts,counts);assert.deepEqual(f.snapshot(),before);assert.equal(f.state.writes,0);});
for(const change of["title","line","move","delete","complete","copied","inactive","missing-dashboard"])
test("selected intent retained but stale candidate submission blocked: "+change,async t=>{
 const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f);t.after(()=>component.close());const selected=reader.state.tasks.find(t=>t.hubTaskId==="parent"),draft=f.draft([selected]);
 if(change==="title"||change==="line"||change==="complete"){const file=f.files.get(selected.path);f.contents.set(file.path,change==="title"?f.contents.get(file.path).replace("Parent **markdown**","Changed"):change==="line"?"\n"+f.contents.get(file.path):f.contents.get(file.path).replace("- [ ] Parent","- [x] Parent"));f.index(file);}
 if(change==="move")f.move(f.files.get(selected.path),"Resources/Knowledge/Moved.md");if(change==="delete")f.remove(f.files.get(selected.path));if(change==="copied")f.add("Outside/Copy.md","- [ ] Copy <!-- hub-task:parent -->\n");if(change==="inactive")f.owners[0].status="shelved";if(change==="missing-dashboard")f.remove(f.files.get(f.owners[0].path));
 await reader.retry();assert.equal(draft.tasks[0],selected);assert.throws(()=>reader.enrollmentDraft(draft));
});
test("failed/incomplete query retains selection and last display, blocks setup, then recovers",async t=>{
 const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f);t.after(()=>component.close());const draft=f.draft(reader.state.tasks.slice(0,1)),before=draft.tasks[0],read=f.adapter.queryStructured.bind(f.adapter);f.adapter.queryStructured=async()=>{throw Error("Index unavailable");};await reader.retry();assert.equal(reader.state.status,"error");assert(reader.state.tasks.length);assert.equal(draft.tasks[0],before);assert.throws(()=>reader.enrollmentDraft(draft),/could not be loaded/);f.adapter.queryStructured=read;await reader.retry();assert.equal(reader.state.status,"ready");assert.equal(reader.enrollmentDraft(draft).tasks[0].text,before.text);
});
test("deferred A/B workspace responses, close and plugin unload never publish stale candidates",async t=>{
 const f=fixture();t.after(()=>f.close());const pending=[],read=f.adapter.queryStructured.bind(f.adapter);f.adapter.queryStructured=async options=>{const q=await read(options),g=gate();pending.push({g,q});return g.promise;};const component=owner(),reader=createOathCandidateRead(f.oath,component);t.after(()=>component.close());const a=reader.selectWorkspace({type:"project",id:"private"});while(pending.length<1)await Promise.resolve();const b=reader.selectWorkspace({type:"resource",id:"study"});while(pending.length<2)await Promise.resolve();pending[1].g.resolve(pending[1].q);await b;const tasks=reader.state.tasks;pending[0].g.resolve(pending[0].q);await a;assert.equal(reader.state.tasks,tasks);assert(tasks.every(t=>t.path.startsWith("Resources/Knowledge/")));
 const c=reader.retry();while(pending.length<3)await Promise.resolve();f.cleanup.forEach(fn=>fn());pending[2].g.resolve(pending[2].q);await c;assert.equal(reader.state.status,"closed");assert.equal(reader.state.tasks,tasks);assert(await f.service.queryHistory({projection:"recorded"}));
});
test("refresh never replaces selection/deselection and accepted enrollment survives consumer disposal",async t=>{
 const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f);const selected=reader.state.tasks.slice(0,2),draft=f.draft(selected),submitted=reader.enrollmentDraft(draft);draft.tasks=[];await reader.retry();assert.equal(draft.tasks.length,0);component.close();await f.oath.take(submitted);assert.equal(f.oath.current.tasks.length,selected.length);
});
test("multiple candidate consumers share one facade backend watcher and dispose only their sessions",async t=>{
 const f=fixture();t.after(()=>f.close());const a=await ready(f),b=await ready(f);assert.equal(f.plugin.taskData.subscribers.size,1);assert.equal(f.cleanup.length,1);a.component.close();assert.equal(f.plugin.taskData.subscribers.size,1);await b.reader.retry();b.component.close();assert.equal(f.plugin.taskData.subscribers.size,0);assert(await f.service.queryHistory({projection:"recorded"}));
});
test("all protected Oath methods remain byte-identical outside the authorized committed reader",()=>{require("./oath-committed-boundaries.cjs").unchangedOath(fs.readFileSync(path.join(__dirname,"oath-candidate-service-original.cjs"),"utf8"),fs.readFileSync(path.join(__dirname,"../services/oath.js"),"utf8"));});
test("cached grouping follows current local start boundaries without another index scan",async t=>{const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f);t.after(()=>component.close());f.oath.now=()=>f.now+10*86400000;const expected=f.read({type:"project",id:"private"}),queries=f.counts.queries;assert.deepEqual(facts(reader.tasks()),facts(expected));assert.equal(f.counts.queries,queries);});
test("accepted source-validated enrollment continues after pending read and consumer close",async t=>{const f=fixture();t.after(()=>f.close());const{reader,component}=await ready(f),draft=f.draft(reader.state.tasks.slice(0,1)),submitted=reader.enrollmentDraft(draft),persist=gate(),save=f.plugin.dataStore.save;let saving=false;f.plugin.dataStore.save=async data=>{saving=true;await persist.promise;return save(data);};const accepted=f.oath.take(submitted);while(!saving)await Promise.resolve();component.close();persist.resolve();await accepted;assert.equal(f.oath.current.tasks.length,1);assert(f.saved);});
test("partial metadata retains unrelated display rows but prevents misleading successful setup",async t=>{const f=fixture();t.after(()=>f.close());Object.defineProperty(f.wizard.data.taskMetadata,"parent",{get(){throw Error("Unavailable metadata");},configurable:true});const{reader,component}=await ready(f);t.after(()=>component.close());assert.equal(reader.state.status,"error");assert(reader.state.tasks.length>0);assert(reader.state.diagnostics.some(d=>d.code==="METADATA_UNAVAILABLE"));assert.throws(()=>reader.enrollmentDraft(f.draft(reader.state.tasks.slice(0,1))),/could not be loaded/);});
test("incomplete global index cannot be accepted as a safe empty candidate list",async t=>{const f=fixture();t.after(()=>f.close());const pages=f.plugin.taskData.readPages;f.plugin.taskData.readPages=(dv,root,onError)=>{onError(null,Error("Lost indexed row"));return pages(dv,root,onError);};const{reader,component}=await ready(f);t.after(()=>component.close());assert.equal(reader.state.status,"error");assert.equal(reader.state.error.code,"INDEX_UNAVAILABLE");assert.equal(f.state.writes+f.counts.persists,0);});
test("active Oath and candidate lifetimes keep independent subscriptions and clock/read separation",async t=>{const f=fixture();t.after(()=>f.close());await f.oath.start();await f.oath.take(f.draft(f.read({type:"project",id:"private"}).slice(0,1)));f.oath.now=()=>f.now+70000;await f.oath.refresh();assert(f.oath.active);const{reader,component}=await ready(f);const watchers=f.plugin.taskData.subscribers.size,queries=f.counts.queries;for(let i=0;i<5;i++){f.oath.tickDisplay();await f.oath.refresh(false);reader.requirements(f.draft(reader.state.tasks.slice(0,1)));}assert.equal(f.counts.queries,queries);component.close();assert.equal(watchers,1);assert.equal(f.plugin.taskData.subscribers.size,watchers);await f.oath.refresh();assert(f.oath.active);});
